#!/usr/bin/env bash
set -euo pipefail
declare draft ROOT
toy=$ROOT/tests/fixtures/toy.glb
ctl scene import "$draft" "$toy" --id toy >/dev/null || fail "no model was imported"
ctl scene act "$draft" scene3d '{"model": {"add": {"asset": "toy", "at": [0, 0, -1], "id": "doll"}}}' || fail "no model layer was added"
ctl scene act "$draft" scene3d '{"model": {"set": {"layer": "doll", "rotation": [0, 30, 0], "scale": [1.5, 1.5, 1.5]}}}' || fail "the model was not placed"
ctl scene act "$draft" scene3d '{"group": {"id": "world", "layers": ["doll"]}}' || fail "no 3D group was made around the model"
scene_doc "$draft" /scene/layers | grep '"space": "3d"' >/dev/null || fail "the group is not 3D"
ctl scene act "$draft" add_layer '{"id": "card", "into": "world", "kind": "solid"}' >/dev/null || fail "no flat layer was added to the 3D group"
ctl scene act "$draft" scene3d '{"depth_test": {"layer": "card", "on": true}}' || fail "the flat layer does not test depth"
ctl scene act "$draft" scene3d '{"material": {"double_sided": true, "emissive": "#ff2000", "layer": "doll", "name": "paint", "shader": "unlit"}}' || fail "the material was not changed"
ctl scene act "$draft" scene3d '{"material": {"layer": "doll", "name": "paint", "params": {"metallic": 0.4, "roughness": 0.3}, "shader": "pbr"}}' || fail "the material took no numbers"
ctl scene act "$draft" scene3d '{"camera": {"center": [0, 0, 0], "eye": [0, 1, 6], "fov": 45}}' || fail "the 3D camera was not set"
ctl scene act "$draft" scene3d '{"camera": {"roll": -15}}' || fail "the 3D camera was not rolled"
ctl scene act "$draft" scene3d '{"camera": {"far": 2}}' || fail "the far plane was not set"
ctl scene act "$draft" scene3d '{"camera": {"far": 1000}}' || fail "the far plane was not set back"
ctl scene act "$draft" scene3d '{"view": {"orbit": [40, 10], "zoom": 0.5}}' || fail "the authoring view did not move"
ctl scene act "$draft" scene3d '{"view": {"frame": "doll"}}' || fail "the authoring view did not frame the model"
ctl scene act "$draft" scene3d '{"camera": {"from_view": true}}' || fail "the camera was not taken from the authoring view"
ctl scene act "$draft" scene3d '{"view": {"orbit": [10, 5]}}' || fail "a 3D edit given as JSON was not applied"
ctl scene act "$draft" scene3d '{"view": {"reset": true}}' || fail "the authoring view was not reset"
ctl scene act "$draft" scene3d '{"tones": {"hdr": true, "split": 0.5, "tonemap": "aces"}}' || fail "the tone map was not set"
ctl pack check "$draft" >/dev/null || fail "the 3D scene is not valid"
ctl scene preview "$draft" -o preview:1 --time 0.2 || fail "the 3D scene was not previewed"
ctl scene act "$draft" scene3d '{"tones": {"hdr": false, "split": 0, "tonemap": "none"}}' || fail "the tone map was not turned off"
rig=$ROOT/tests/fixtures/rig.glb
ctl scene import "$draft" "$rig" --id rig3d >/dev/null || fail "no rigged model was imported"
ctl scene act "$draft" scene3d '{"model": {"add": {"asset": "rig3d", "id": "walker", "into": "world"}}}' || fail "no rigged model layer was added"
ctl scene act "$draft" clip '{"add": true, "id": "bend", "layer": "walker"}' || fail "no clip was added to the model"
ctl scene act "$draft" clip '{"animation": "bend", "from": 0.5, "id": "bend", "layer": "walker"}' || fail "the clip did not take the animation of the file"
ctl scene act "$draft" key '{"angles": [0, 0, 30], "bone": "tip", "clip": "bend", "layer": "walker", "time": 0.5}' || fail "no 3D key was set"
ctl scene act "$draft" key '{"bone": "tip", "clip": "bend", "layer": "walker", "shift": [0, 0.1, 0], "time": 0.5}' || fail "no 3D shift was keyed"
ctl scene act "$draft" key '{"angles": [0, 0, 0], "bone": "tip", "clip": "bend", "layer": "walker", "out_handle": [0.25, 0.3], "time": 0}' || fail "a 3D key took no Bézier handle"
ctl scene act "$draft" key '{"angles": [0, 0, 30], "bone": "tip", "clip": "bend", "ease": "in_out_sine", "layer": "walker", "time": 0.5}' || fail "a 3D key took no easing"
ctl scene act "$draft" animate '{"layer": {"add": "bend", "layer": "walker"}}' || fail "no animation layer was added"
ctl scene act "$draft" animate '{"layer": {"blend_in": 0.3, "bones": ["tip"], "index": 0, "layer": "walker", "rate": 2, "weight": 0.5}}' || fail "the animation layer was not tuned"
ctl scene act "$draft" animate '{"root": {"layer": "walker", "on": true}}' || fail "root motion was not turned on"
ctl scene act "$draft" animate '{"preset": {"bone": "tip", "layer": "walker", "preset": "hair"}}' || fail "the physics preset was not applied"
ctl scene act "$draft" physics '{"bones": ["tip"], "layer": "walker", "rotation": [-20, 40], "wind": 0.5}' || fail "the swing of a model bone was not bounded"
ctl scene act "$draft" animate '{"morph": {"layer": "walker", "shape": "bulge", "weight": 0.6}}' || fail "the blend shape was not weighed"
ctl scene act "$draft" scene3d '{"material": {"layer": "doll", "name": "paint", "params": {"comb_x": 0.4, "layers": 12, "length": 20}, "shader": "fur"}}' || fail "no fur"
ctl scene act "$draft" scene3d '{"material": {"key": "#00ff00", "layer": "walker", "name": "body", "params": {"threshold": 0.3}, "shader": "chroma"}}' || fail "no chroma key"
ctl scene act "$draft" scene3d '{"new_material": {"name": "gloss_coat"}}' || fail "no material shader was started"
ctl scene act "$draft" scene3d '{"material": {"layer": "doll", "name": "paint", "shader": "gloss_coat"}}' || fail "the package material was not picked"
ctl scene act "$draft" add_layer '{"id": "sun", "kind": "light"}' >/dev/null || fail "no light was added"
ctl scene act "$draft" scene3d '{"shadows": {"bias": 0.3, "layer": "sun", "on": true, "resolution": 1024}}' || fail "the light casts no shadows"
ctl scene act "$draft" scene3d '{"debug": {"show": "shadows"}}' || fail "the 3D debug view did not show shadows"
ctl scene act "$draft" scene3d '{"debug": {}}' || fail "the 3D debug view did not go back to the light"
ctl scene act "$draft" scene3d '{"path": {"add": {"id": "tour"}}}' || fail "no camera path was added"
ctl scene act "$draft" scene3d '{"path": {"key": {"center": [0, 0, 0], "eye": [2, 1, 6], "fov": 40, "path": "tour", "time": 4}}}' || fail "no path key was set"
ctl scene act "$draft" scene3d '{"path": {"key": {"from": 4, "path": "tour", "time": 3}}}' || fail "the path key was not moved in time"
ctl scene act "$draft" scene3d '{"path": {"set": {"ease": "in_out_sine", "loop": true, "path": "tour"}}}' || fail "the path does not loop"
ctl scene act "$draft" scene3d '{"path": {"order": {"order": "random"}}}' || fail "the paths were not ordered"
ctl scene act "$draft" scene3d '{"path": {"fade": {"duration": 0.5, "to": "cross"}}}' || fail "the paths were not faded"
ctl pack check "$draft" >/dev/null || fail "the animated 3D scene is not valid"
ctl scene preview "$draft" -o preview:1 --time 0.5 || fail "the animated 3D scene was not previewed"
ctl scene act "$draft" scene3d '{"path": {"remove": {"path": "tour"}}}' || fail "the path was not removed"
ctl scene act "$draft" scene3d '{"camera": {"clear": true}}' || fail "the 3D camera was not removed"
ctl scene act "$draft" remove_layer '{"id": "world"}' >/dev/null || fail "the 3D group was not removed"
